metadata.globalCss:
.complex-hero-slider {position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;}

.complex-hero-video {position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  pointer-events: none;}

.complex-hero-slide {position: absolute;
  inset: 0;
  background: var(--image) center / cover no-repeat;
  opacity: 0;
  transform: scale(1.02);
  transition: opacity .8s ease, transform 6s ease;}

.complex-hero-copy {position: relative;
  z-index: 2;
  width: min(100%, 1220px);
  margin: 0 auto;
  padding: 0 0 clamp(28px, 6vw, 74px);}

.project-logo-mark {display: block;
  width: min(420px, 58vw);
  height: auto;
  object-fit: contain;
  filter: drop-shadow(0 18px 28px rgba(0, 0, 0, .28));}

.hero-tools {position: absolute;
  right: clamp(18px, 4vw, 72px);
  bottom: clamp(22px, 4vw, 60px);
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 10px;}

/* ============================================================
   БЛОК: HERO — обложка жилого комплекса (слайдер/видео,
   название проекта, инструменты слайдера).
   Содержимое (фото, название, класс) подставляет page.js
   по параметру ?project= из URL.
   ============================================================ */

.complex-hero-detail {
  position: relative;
  min-height: clamp(520px, 62vw, 720px);
  display: flex;
  align-items: flex-end;
  padding: clamp(18px, 3vw, 42px);
  background: var(--hero-image) center / cover no-repeat;
  color: #fff;
  isolation: isolate;
  overflow: hidden;
}

.complex-hero-detail::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(180deg, rgba(13, 15, 18, .22), rgba(13, 15, 18, .68));
}

.complex-hero-detail.has-video .complex-hero-video {
  opacity: 1;
  object-position: center top;
}

.complex-hero-detail.has-video .complex-hero-slider,
.complex-hero-detail.has-video .hero-tools {
  display: none;
}

.complex-hero-slide.is-active {
  opacity: 1;
  transform: scale(1);
}

.complex-hero-copy .badge {
  display: inline-flex;
  margin-bottom: 14px;
  padding: 9px 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, .18);
  color: #fff;
  font-size: 13px;
  font-weight: 800;
  backdrop-filter: blur(12px);
}

.complex-hero-copy h1 {
  max-width: 680px;
  font-size: clamp(48px, 8vw, 104px);
  line-height: .9;
  letter-spacing: 0;
}

.project-logo-mark.logo-dostlik {
  width: min(460px, 64vw);
  filter: drop-shadow(0 18px 28px rgba(0, 0, 0, .28));
}

.complex-hero-copy p {
  max-width: 560px;
  margin-top: 20px;
  color: rgba(255, 255, 255, .78);
  font-size: clamp(16px, 1.4vw, 20px);
  line-height: 1.5;
}

.hero-tools button {
  min-height: 46px;
  border: 1px solid rgba(255, 255, 255, .24);
  border-radius: 15px;
  background: rgba(255, 255, 255, .18);
  color: #fff;
  padding: 0 16px;
  font-weight: 800;
  cursor: pointer;
  backdrop-filter: blur(14px);
}

@media (max-width: 980px) {
  .complex-hero-detail {
    min-height: 560px;
  }
}

@media (max-width: 760px) {
  .complex-hero-detail {
    min-height: 620px;
  }

  .hero-tools {
    right: 18px;
    left: 18px;
    justify-content: space-between;
  }
}

@media (max-width: 560px) {
  .complex-hero-detail {
    min-height: 520px;
    padding: 18px;
  }

  .complex-hero-copy {
    padding-bottom: 70px;
  }

  .complex-hero-copy h1 {
    font-size: 52px;
    line-height: .95;
  }

  .complex-hero-copy p {
    max-width: 100%;
    font-size: 16px;
  }

  .hero-tools {
    right: 12px;
    bottom: 14px;
    left: 12px;
    gap: 8px;
  }

  .gallery-count,
  .hero-tools button {
    min-height: 42px;
  }
}

@media (max-width: 380px) {
  .complex-hero-copy h1 {
    font-size: 46px;
  }
}
/* ==== hero-sold-out v1 ==== */
.hero-sold {
  display: contents;
}

.complex-hero-copy .badge--sold {
  margin-left: 8px;
  background: #050505;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}
